```python
def find_top_two_majority_elements(nums):
    def majority_element(nums):
        candidate = None
        count = 0

        for num in nums:
            if count == 0:
                candidate = num
            count += (1 if num == candidate else -1)

        return candidate, count

    nums.sort(key=nums.count, reverse=True)

    if len(nums) < 2 or nums[0] != nums[1]:
        return []

    top_two = [nums[0]]
    for num in nums[1:]:
        if nums.count(num) > 0 and len(top_two) < 2:
            top_two.append(num)
        if len(top_two) == 2:
            break

    candidate1, count1 = majority_element(top_two[0])
    candidate2, count2 = majority_element(top_two[1])

    if count1 > len(nums) // 2:
        return [candidate1, candidate2]
    elif count2 > len(nums) // 2:
        return [candidate2, candidate1]
    else:
        return []

# 예제 사용
nums = [3, 3, 4, 2, 4, 4, 2, 4, 4]
print(find_top_two_majority_elements(nums))  # 함수는 출력: [4, 3]
```

